from genesis.engine.solvers.rigid.stress.solve import *

@qd.func
def func_residual_tiled(young: float, tolerance: float, absolute_tolerance: float, stress_state: StressState, stress_info: StressInfo, only_active: qd.template()):
    for i_b in range(stress_state.active.shape[0]):
        if qd.static(not only_active) or stress_state.active[i_b]:
            stress_state.residual_norm_squared[i_b] = 0.0
    qd.loop_config(block_dim=256)
    for i_thread in range(stress_info.vertices.shape[0] * ((stress_state.active.shape[0] + 31) // 32) * 32):
        i_index = i_thread // 32
        i_n = i_index % stress_info.vertices.shape[0]
        i_b = i_index // stress_info.vertices.shape[0] * 32 + i_thread % 32
        if i_b < stress_state.active.shape[0]:
            if qd.static(not only_active) or stress_state.active[i_b]:
                product = qd.Vector.zero(gs.qd_float, 3)
                for i_entry in range(stress_info.row_start[i_n], stress_info.row_start[i_n + 1]):
                    j_n = stress_info.columns[i_entry]
                    product += young * stress_info.stiffness[i_entry] @ stress_state.displacement[j_n, i_b]
                residual = stress_state.rhs[i_n, i_b] - product
                stress_state.residual[i_n, i_b] = residual
                qd.atomic_add(stress_state.residual_norm_squared[i_b], residual.dot(residual))
    for i_b in range(stress_state.active.shape[0]):
        if qd.static(not only_active) or stress_state.active[i_b]:
            budget = qd.max(absolute_tolerance * absolute_tolerance, tolerance * tolerance * stress_state.rhs_norm_squared[i_b])
            norm = stress_state.residual_norm_squared[i_b]
            stress_state.valid[i_b] = stress_state.valid[i_b] and (not qd.math.isinf(norm)) and (not qd.math.isnan(norm)) and (norm <= budget)

@qd.kernel(graph=True)
def kernel_residual_tiled(
    young: float, tolerance: float, absolute_tolerance: float,
    stress_state: StressState, stress_info: StressInfo, only_active: qd.template(),
):
    func_residual_tiled(young, tolerance, absolute_tolerance, stress_state, stress_info, only_active)
